#include <string.h>
#include "ringbuf.h"

int main(void)
{
    ringbuf_t *rb;
    size_t n;
    uint8_t buf[16];
    uint8_t indata[] = { 0x00, 0x01, 0x02, 0x03, 0x04 };

    /* basic create / destroy */
    rb = rb_create(32);
    if (!rb) { printf("FAIL: rb_create\n"); return 1; }

    /* capacity */
    if (rb_capacity(rb) != 32) { printf("FAIL: capacity"); return 1; }

    /* write some data, check size */
    n = rb_write(rb, indata, sizeof(indata));
    if (n != 5) { printf("FAIL: write %zu\n", n); return 1; }
    if (rb_size(rb) != 5) { printf("FAIL: size after write"); return 1; }

    /* peek matches what was written */
    memset(buf, 0, sizeof(buf));
    n = rb_peek(rb, buf, 3);
    if (n != 3 || memcmp(buf, indata, 3) != 0) { printf("FAIL: peek"); return 1; }

    /* read back exactly */
    memset(buf, 0, sizeof(buf));
    n = rb_read(rb, buf, 5);
    if (n != 5 || memcmp(buf, indata, 5) != 0) { printf("FAIL: read"); return 1; }
    if (rb_size(rb) != 0) { printf("FAIL: size after read"); return 1; }

    /* wrap-around test: write more than capacity so data spans end of storage */
    memset(indata, 0xAA, sizeof(indata));
    rb_write(rb, indata, 32);         /* fills buffer completely */
    rb_read(rb, buf, 16);              /* read half  */
    rb_write(rb, indata + 8, 16);     /* wraps around the end */

    memset(buf, 0, sizeof(buf));
    n = rb_read(rb, buf, 32);         /* should get everything back */
    if (n != 32) { printf("FAIL: wrap read count %zu\n", n); return 1; }

    /* partial write fills only what fits */
    rb_clear(rb);
    memset(indata, 0xBB, sizeof(indata));
    n = rb_write(rb, indata, 64);     /* buffer holds only 32 */
    if (n != 32) { printf("FAIL: partial write %zu\n", n); return 1; }

    /* NULL safety */
    rb_destroy(NULL);
    if (rb_size(NULL) != 0) { printf("FAIL: size(NULL)"); return 1; }

    /* invalid create */
    if (rb_create(0) != NULL) { printf("FAIL: create(0)"); return 1; }

    rb_destroy(rb);
    printf("All tests passed!\n");
    return 0;
}

